class Solution {
  public int findLength(int[] nums1, int[] nums2) {
    int m = nums1.length, n = nums2.length, best = 0;
    int[] dp = new int[n + 1];
    for (int i = 1; i <= m; i++) {
      for (int j = n; j >= 1; j--) {
        dp[j] = nums1[i - 1] == nums2[j - 1] ? dp[j - 1] + 1 : 0;
        best = Math.max(best, dp[j]);
      }
    }
    return best;
  }
}
